<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import axios from 'axios'
const tab=ref('creatives'),busy=ref(false),error=ref(''),notice=ref(''),creatives=ref<any[]>([]),rules=ref<any[]>([]),genres=ref<any[]>([])
const catalogGenre=ref<number|null>(null)
const title=ref(''),file=ref<File|null>(null),preview=ref(''),kind=ref('movie'),q=ref(''),offset=ref(0),total=ref(0),videos=ref<any[]>([]),selected=ref<any>(null),cues=ref<any[]>([]),revision=ref(0),source=ref(''),mainUrl=ref(''),main=ref<HTMLVideoElement|null>(null),position=ref(0),duration=ref(0),timeInput=ref('00:00:00'),cueKind=ref('mid'),creativeId=ref('')
const uuid=()=>crypto.randomUUID?.()||'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16))
const freshRule=()=>({id:uuid(),scope:'all',genre_id:null as number|null,enabled:false,preroll:true,postroll:false,interval_sec:1200,creative_id:null as string|null})
const rule=ref(freshRule())
const headers=()=>({Authorization:'Bearer '+(localStorage.getItem('admin_token')||'cookie-session')})
const base='/api/v1/admin/ads'
let previewSession='',previewBeat:ReturnType<typeof setInterval>|null=null
async function stopPreview(){if(previewBeat)clearInterval(previewBeat);previewBeat=null;const id=previewSession;previewSession='';main.value?.pause();mainUrl.value='';if(id)try{await axios.post('/api/v1/playback/stop',{session_id:id},{headers:headers(),timeout:5000})}catch{/* Lease expires if the connection was lost. */}}
onBeforeUnmount(()=>{void stopPreview()})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:'Не удалось выполнить операцию. Проверьте настройки и повторите.'}finally{busy.value=false}}
async function load(){creatives.value=(await axios.get(base+'/creatives',{headers:headers()})).data;rules.value=(await axios.get(base+'/rules',{headers:headers()})).data}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
function upload(){void action(async()=>{if(!file.value||!title.value.trim())throw Error();if(file.value.size>104857600){error.value='Максимальный размер — 100 МиБ';return}await axios.get('/api/v1/auth/me',{timeout:10000});await axios.post(base+'/creatives/upload',file.value,{params:{title:title.value.trim()},headers:{...headers(),'Content-Type':file.value.type||(/\.webm$/i.test(file.value.name)?'video/webm':'video/mp4')},timeout:240000});file.value=null;title.value='';await load();notice.value='Ролик обработан и сохранён на паузе'})}
function saveCreative(c:any){void action(async()=>{await axios.put(base+'/creatives/'+c.id,{title:c.title,cta_url:c.cta_url,cta_text:c.cta_text,skip_after:c.skip_after==null?null:Number(c.skip_after),status:c.status},{headers:headers()});await load();notice.value='Настройки ролика сохранены'})}
function showPreview(c:any){void action(async()=>{preview.value=(await axios.get(base+'/creatives/'+c.id+'/preview',{headers:headers()})).data.media_url})}
async function catalog(){const r=await axios.get(base+'/videos',{params:{kind:kind.value,q:q.value,offset:offset.value,genre_id:catalogGenre.value??undefined},headers:headers()});videos.value=r.data.items;total.value=r.data.total}
function search(){offset.value=0;void action(catalog)}
function page(n:number){offset.value+=n;void action(catalog)}
function format(s:number){return [Math.floor(s/3600),Math.floor(s%3600/60),Math.floor(s%60)].map(x=>x.toString().padStart(2,'0')).join(':')}
function parse(v:string){if(!/^\d{2}:\d{2}:\d{2}$/.test(v))throw Error('Время: ЧЧ:ММ:СС');const [h,m,s]=v.split(':').map(Number);if(m>59||s>59||h>6)throw Error('Некорректное время');return h*3600+m*60+s}
async function loadTimeline(){const r=(await axios.get(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()})).data;cues.value=r.cues;revision.value=r.revision;source.value=r.source}
function openVideo(v:any){void action(async()=>{await stopPreview();selected.value=v;duration.value=v.duration_sec||0;position.value=0;await loadTimeline()})}
function startPreview(){void action(async()=>{if(!selected.value)return;await stopPreview();const path=selected.value.kind==='movie'?'/api/v1/playback/start':'/api/v1/series_playback/start';const body=selected.value.kind==='movie'?{movie_id:selected.value.id}:{episode_id:selected.value.id};const r=await axios.post(path,body,{headers:headers()});mainUrl.value=r.data.media_url;if(r.data.session_id){previewSession=r.data.session_id;previewBeat=setInterval(()=>{if(previewSession)void axios.post('/api/v1/playback/heartbeat',{session_id:previewSession},{headers:headers(),timeout:5000}).catch(()=>{})},Math.max(5,r.data.heartbeat_interval_seconds||15)*1000)}})}
function addCue(){try{const seconds=cueKind.value==='mid'?parse(timeInput.value):0;if(cueKind.value==='mid'&&seconds<=0)throw Error('Mid-roll должен быть позже начала');if(cues.value.some(c=>c.kind===cueKind.value&&c.at_sec===seconds))throw Error('Такая точка уже есть');cues.value.push({id:uuid(),kind:cueKind.value,at_sec:seconds,creative_id:creativeId.value||null});error.value=''}catch(e:any){error.value=e.message}}
function seek(e:Event){position.value=Number((e.target as HTMLInputElement).value);timeInput.value=format(position.value);if(main.value)main.value.currentTime=position.value}
function move(c:any,e:Event){try{c.at_sec=parse((e.target as HTMLInputElement).value);error.value=''}catch(e:any){error.value=e.message}}
function saveTimeline(){void action(async()=>{const r=await axios.put(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{revision:revision.value,cues:cues.value},{headers:headers()});revision.value=r.data.revision;source.value='individual';notice.value='Индивидуальные тайминги сохранены';await catalog()})}
function inherit(){if(!confirm('Удалить индивидуальные настройки и применять глобальное правило?'))return;void action(async()=>{await axios.delete(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()});await loadTimeline();await catalog()})}
function saveRule(){if(!confirm('Сохранить правило? Оно применяется к доступным видео выбранной области. Индивидуальные настройки сохраняют приоритет.'))return;void action(async()=>{const {id,...body}=rule.value;await axios.put(base+'/rules/'+id,body,{headers:headers()});await load();notice.value='Глобальное правило сохранено'})}
function removeRule(id:string){if(!confirm('Удалить правило?'))return;void action(async()=>{await axios.delete(base+'/rules/'+id,{headers:headers()});await load();rule.value=freshRule()})}
const ordered=computed(()=>[...cues.value].sort((a,b)=>(a.kind==='pre'?-1:a.kind==='post'?1:0)-(b.kind==='pre'?-1:b.kind==='post'?1:0)||a.at_sec-b.at_sec))
onMounted(()=>void action(async()=>{await load();await catalog();try{genres.value=(await axios.get('/api/v1/genres',{headers:headers()})).data}catch{genres.value=[]}}))
</script>
<template>
<section class="studio"><header><span class="eyebrow">PRIVATE CONTROL PLANE</span><h1>Видео и Реклама <span>Ad Studio</span></h1><p>Ролики, тайминги и массовые правила. Основное видео и рекламное хранилище изолированы.</p></header>
<nav aria-label="Вкладки Ad Studio"><button v-for="t in [{id:'creatives',label:'Библиотека роликов'},{id:'timeline',label:'Видео и тайминги'},{id:'rules',label:'Глобальные правила'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.label}}</button></nav>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p><p v-if="busy" role="status">Обработка…</p>
<div v-if="tab==='creatives'"><form class="panel upload" @submit.prevent="upload"><h2>Новый рекламный ролик</h2><label>Название кампании / ролика<input v-model="title" maxlength="160" required></label><label>Видео MP4 / WebM · до 100 МиБ · 0,5–300 сек<input type="file" accept="video/mp4,video/webm,.mp4,.webm" required @change="selectFile"></label><button :disabled="busy">Загрузить и обработать</button></form>
<video v-if="preview" :src="preview" controls class="preview"></video>
<p v-if="!creatives.length" class="empty">Библиотека пуста. Загруженные ролики сохраняются на паузе.</p>
<article v-for="c in creatives" :key="c.id" class="panel"><div class="row"><h2>{{c.title}}</h2><span>{{c.duration_sec.toFixed(1)}} сек · {{(c.byte_size/1048576).toFixed(1)}} МиБ</span><button :disabled="busy" @click="showPreview(c)">Предпросмотр</button></div><div class="grid"><label>Название<input v-model="c.title" maxlength="160"></label><label>CTA URL<input v-model="c.cta_url" type="url" placeholder="https://…"></label><label>Текст CTA-кнопки<input v-model="c.cta_text" maxlength="80" placeholder="Пусто — не показывать"></label><label>Статус<select v-model="c.status"><option value="active">Активен</option><option value="paused">На паузе</option></select></label><label>Пропуск<select :value="c.skip_after==null?'no':'yes'" @change="c.skip_after=($event.target as HTMLSelectElement).value==='no'?null:5"><option value="no">Без пропуска</option><option value="yes">Разрешить через X секунд</option></select></label><label v-if="c.skip_after!=null">Через X секунд<input v-model.number="c.skip_after" type="number" min="1" :max="Math.floor(c.duration_sec-1)"></label></div><div class="row stats"><span>Показы <b>{{c.impressions}}</b></span><span>Досмотры <b>{{c.completions}}</b></span><span>Клики <b>{{c.clicks}}</b></span><button :disabled="busy" @click="saveCreative(c)">Сохранить ролик</button></div></article></div>
<div v-if="tab==='timeline'"><form class="row panel" @submit.prevent="search"><select v-model="kind" @change="search"><option value="movie">Фильмы</option><option value="episode">Серии сериалов</option></select><select v-model="catalogGenre" @change="search"><option :value="null">Все категории</option><option v-for="g in genres" :key="g.id" :value="g.id">{{g.name}}</option></select><input v-model="q" placeholder="Быстрый поиск" maxlength="120"><button :disabled="busy">Найти</button><span>Доступно: {{total}}</span></form><div class="editor"><aside class="panel catalog"><button v-for="v in videos" :key="v.id" :class="{active:selected?.id===v.id}" @click="openVideo(v)"><strong>{{v.title}}</strong><small>{{v.cue_count+' точек · '+(v.override?'индивидуально':'глобально')}}</small></button><div class="row"><button :disabled="busy||offset===0" @click="page(-30)">Назад</button><button :disabled="busy||offset+30>=total" @click="page(30)">Далее</button></div></aside><div v-if="selected" class="panel timeline"><h2>{{selected.title}}</h2><p>Источник: {{source==='individual'?'индивидуальные настройки':source==='global'?'глобальное правило':'не настроено'}}</p><button :disabled="busy" @click="startPreview">Загрузить предпросмотр видео</button><video v-if="mainUrl" ref="main" class="preview" :src="mainUrl" controls @loadedmetadata="duration=main?.duration||duration" @timeupdate="position=main?.currentTime||0;timeInput=format(position)"></video><label>Шкала времени · {{format(position)}}<input type="range" min="0" :max="duration||21600" step="1" :value="position" @input="seek"></label><div class="markers"><button v-for="c in ordered" :key="c.id" :style="{left:(c.kind==='pre'?0:c.kind==='post'?100:100*c.at_sec/(duration||21600))+'%'}" :title="c.kind+' '+format(c.at_sec)" @click="position=c.at_sec;timeInput=format(c.at_sec)">◆</button></div><div class="row"><select v-model="cueKind"><option value="pre">Pre-roll · начало</option><option value="mid">Mid-roll</option><option value="post">Post-roll · конец</option></select><input v-if="cueKind==='mid'" v-model="timeInput" aria-label="Точное время" placeholder="ЧЧ:ММ:СС"><select v-model="creativeId"><option value="">Ротация активных роликов</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}} · {{c.status}}</option></select><button @click="addCue">Добавить точку</button></div><div v-for="c in ordered" :key="c.id" class="row cue"><b>{{c.kind}}</b><input v-if="c.kind==='mid'" :value="format(c.at_sec)" aria-label="Переместить точку" @change="move(c,$event)"><span v-else>{{c.kind==='pre'?'Начало':'Конец'}}</span><select v-model="c.creative_id"><option :value="null">Ротация активных</option><option v-for="ad in creatives" :key="ad.id" :value="ad.id">{{ad.title}}</option></select><button @click="cues=cues.filter(x=>x.id!==c.id)">Удалить</button></div><p>Пустой индивидуальный список отключает рекламу в этом видео.</p><div class="row"><button :disabled="busy" @click="saveTimeline">Сохранить тайминги</button><button :disabled="busy" @click="inherit">Наследовать глобальное правило</button></div></div><div v-else class="panel empty">Выберите фильм или серию для настройки таймингов.</div></div></div>
<div v-if="tab==='rules'" class="panel"><h2>Массовые шаблоны</h2><p>Правило действует сразу для выбранной области. Индивидуальные настройки видео всегда важнее. Категория имеет приоритет над общим правилом.</p><div class="row"><button @click="rule=freshRule()">Новое правило</button><button v-for="r in rules" :key="r.id" @click="rule={...r}">{{r.scope}} · {{r.genre_id?('жанр #'+r.genre_id):'все категории'}} · {{r.enabled?'включено':'на паузе'}}</button></div><form class="grid" @submit.prevent="saveRule"><label>Область<select v-model="rule.scope"><option value="all">Все видео</option><option value="movie">Все фильмы</option><option value="episode">Все серии</option></select></label><label>Категория<select v-model="rule.genre_id"><option :value="null">Все категории</option><option v-for="g in genres" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>Ролик<select v-model="rule.creative_id"><option :value="null">Ротация активных</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label>Mid-roll каждые N минут (0 — выключено)<input type="number" min="0" max="120" :value="rule.interval_sec/60" @input="rule.interval_sec=Number(($event.target as HTMLInputElement).value)*60"></label><label><input v-model="rule.preroll" type="checkbox"> Pre-roll в начале</label><label><input v-model="rule.postroll" type="checkbox"> Post-roll в конце</label><label><input v-model="rule.enabled" type="checkbox"> Правило активно</label><div class="row"><button :disabled="busy">Сохранить правило</button><button type="button" :disabled="busy" @click="removeRule(rule.id)">Удалить</button></div></form></div>
</section></template>
<style scoped>
.studio{max-width:1400px;margin:0 auto;padding:28px;color:#e2e8f0}.eyebrow{font-size:11px;letter-spacing:.18em;color:#8b9ab2}h1{font-size:30px;margin:10px 0}h1 span{color:#7da8ff;font-weight:400}h2{font-size:18px}p{color:#a5b3c8;line-height:1.6}nav,.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}nav{margin:24px 0}.panel{padding:20px;background:#141d2a;border:1px solid #2b3748;border-radius:12px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:20px 0}label{display:flex;flex-direction:column;gap:8px;font-size:13px;color:#b8c5d8}input,select,button{font:inherit;border-radius:7px;border:1px solid #3b4a62;padding:10px;background:#0d1521;color:#e2e8f0}button{cursor:pointer}button:hover,button.active,nav .active{background:#254a85;border-color:#5587dc}button:disabled{opacity:.5;cursor:wait}input[type=checkbox]{align-self:flex-start}.upload{display:grid;gap:16px;grid-template-columns:1fr 2fr 2fr auto;align-items:end}.preview{display:block;width:100%;max-height:450px;background:#000;margin:16px 0}.error{background:#611c2a;padding:12px;border-radius:8px;color:#ffd9dd}.notice{background:#124539;padding:12px;border-radius:8px;color:#ccfbe9}.stats{margin-top:18px}.stats b{margin-left:8px;color:#fff}.editor{display:grid;grid-template-columns:300px 1fr;gap:20px}.catalog{max-height:850px;overflow:auto}.catalog>button{display:block;text-align:left;width:100%;margin:6px 0}.catalog small{display:block;color:#a1afc5;margin-top:8px}.timeline{min-width:0}.cue{margin:10px 0;padding:10px;border-bottom:1px solid #2b3748}.cue input{width:110px}.markers{position:relative;height:30px;margin:0 15px 20px}.markers button{position:absolute;padding:0;border:0;background:transparent;transform:translateX(-50%);color:#85b4ff}.empty{padding:40px;color:#92a4be}@media(max-width:1000px){.editor{grid-template-columns:1fr}.upload{grid-template-columns:1fr}.studio{padding:16px}}
</style>
